        auth.setApiClient(client);

        await expectLater(
          auth.exchangeCode('bad-code'),
          throwsA(
            isA<OpenAPIException>().having(
              (e) => '$e',
              'text',
              contains('invalid_grant'),
            ),
          ),
        );
      },
    );
  });
}
